package org.apache.commons.math.stat.descriptive;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.StorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.moment.GeometricMean;
import org.apache.commons.math.stat.descriptive.moment.Mean;
import org.apache.commons.math.stat.descriptive.moment.SecondMoment;
import org.apache.commons.math.stat.descriptive.moment.Variance;
import org.apache.commons.math.stat.descriptive.rank.Max;
import org.apache.commons.math.stat.descriptive.rank.Min;
import org.apache.commons.math.stat.descriptive.summary.Sum;
import org.apache.commons.math.stat.descriptive.summary.SumOfLogs;
import org.apache.commons.math.stat.descriptive.summary.SumOfSquares;
import org.apache.commons.math.stat.descriptive.univariate.GeometricMean;
import org.apache.commons.math.stat.descriptive.univariate.Mean;
import org.apache.commons.math.stat.descriptive.univariate.Variance;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math.util.Precision;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for SummaryStatistics.addValue
 */
public class SummaryStatistics_addValue_TriageGen3Test {

    private SummaryStatistics stats;

    @Before
    public void setUp() {
        stats = new SummaryStatistics();
    }

    @Test
    public void testAddValue_StandardFlow() {
        double value = 10.5;
        stats.addValue(value);

        assertEquals(1, stats.getN());
        assertEquals(value, stats.getSum(), 1e-10);
        assertEquals(value * value, stats.getSumsq(), 1e-10);
        assertEquals(value, stats.getMin(), 1e-10);
        assertEquals(value, stats.getMax(), 1e-10);
        assertEquals(Math.log(value), stats.getSumOfLogs(), 1e-10);
        assertEquals(value * value, stats.getSecondMoment(), 1e-10);
        assertEquals(value, stats.getMean(), 1e-10);
        assertEquals(0.0, stats.getVariance(), 1e-10);
        assertEquals(value, stats.getGeometricMean(), 1e-10);
    }

    @Test
    public void testAddValue_MultipleValues() {
        stats.addValue(2.0);
        stats.addValue(4.0);

        assertEquals(2, stats.getN());
        assertEquals(6.0, stats.getSum(), 1e-10);
        assertEquals(20.0, stats.getSumsq(), 1e-10); // 4 + 16
        assertEquals(2.0, stats.getMin(), 1e-10);
        assertEquals(4.0, stats.getMax(), 1e-10);
        assertEquals(3.0, stats.getMean(), 1e-10);
        // Variance formula for [2, 4] is ((2-3)^2 + (4-3)^2) / (2-1) = 2
        assertEquals(2.0, stats.getVariance(), 1e-10);
    }

    @Test
    public void testAddValue_WithOverriddenMean() {
        // To cover the 'if (!(meanImpl instanceof Mean))' branch
        // We mock a class that IS an instance of Mean
        Mean mockedMean = mock(Mean.class);
        StorelessUnivariateStatistic mockedSum = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockedSumsq = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockedMin = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockedMax = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockedSumLog = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockedSecondMoment = mock(StorelessUnivariateStatistic.class);
        StorelessUnivariateStatistic mockedVariance = mock(Variance.class);
        StorelessUnivariateStatistic mockedGeoMean = mock(GeometricMean.class);

        stats.setSumImpl(mockedSum);
        stats.setSumsqImpl(mockedSumsq);
        stats.setMinImpl(mockedMin);
        stats.setMaxImpl(mockedMax);
        stats.setSumLogImpl(mockedSumLog);
        stats.setMeanImpl(mockedMean); // This is an instance of Mean
        stats.setVarianceImpl(mockedVariance);
        stats.setGeoMeanImpl(mockedGeoMean);

        // We need to use reflection or a way to set the second moment if it's not a standard impl, 
        // but since secondMoment is a field in the class usually initialized internally, 
        // we test the logic via the public API or assume standard init.
        // However, the method signature shows secondMoment.increment(value). 
        // Since we can't easily set secondMoment via setters in the provided signature, 
        // we rely on the standard behavior for the second moment.

        double value = 5.0;
        stats.addValue(value);

        // Verify standard components incremented
        verify(mockedSum).increment(value);
        verify(mockedSumsq).increment(value);
        verify(mockedMin).increment(value);
        verify(mockedMax).increment(value);
        verify(mockedSumLog).increment(value);

        // Verify mean was NOT incremented because it IS an instance of Mean
        verify(mockedMean, org.mockito.Mockito.never()).increment(value);

        // Verify variance and geoMean WERE incremented because they are NOT instances of Variance/GeometricMean 
        // (Mocking them as the specific types satisfies the 'instanceof' check)
        verify(mockedVariance).increment(value);
        verify(mockedGeoMean).increment(value);
    }

    @Test
    public void testAddValue_WithOverriddenVarianceAndGeoMean() {
        // To cover the other branches of the if statements
        Variance mockedVariance = mock(Variance.class);
        GeometricMean mockedGeoMean = mock(GeometricMean.class);
        Mean mockedMean = mock(Mean.class);

        stats.setMeanImpl(mockedMean);
        stats.setVarianceImpl(mockedVariance);
        stats.setGeoMeanImpl(mockedGeoMean);

        double value = 1.0;
        stats.addValue(value);

        // meanImpl is Mean -> do nothing
        verify(mockedMean, org.mockito.Mockito.never()).increment(value);
        // varianceImpl is Variance -> do nothing
        verify(mockedVariance, org.mockito.Mockito.never()).increment(value);
        // geoMeanImpl is GeometricMean -> do nothing
        verify(mockedGeoMean, org.mockito.Mockito.never()).increment(value);
    }
}
